"""Create a compact comparison from collected, immutable per-run evidence."""
import json,pathlib
root=pathlib.Path(__file__).resolve().parent;e=root/'evidence'
load=lambda path:json.loads(path.read_text())
rows=[]
for n in [8,16]:
 c=load(e/f'u{n}/cpu-r1/result.json');g=load(e/f'u{n}/gpu-r1/result.json');cr=c['metrics']['real_time_ratio'];gr=g['metrics']['real_time_ratio']
 rows.append(dict(ues=n,cpu_radio_wall=cr,gpu_radio_wall=gr,progress_speed_change_percent=(gr/cr-1)*100,cpu_valid_segments=c['valid_segments'],gpu_valid_segments=g['valid_segments'],measured_segments=30,quality='All 30 report segments valid in both modes' if n==8 else 'Connection loss during measurement; descriptive rates only'))
c=load(e/'u16/cpu-trace-r1/trace-summary.json');g=load(e/'u16/gpu-trace-r1/trace-summary.json');cg=c['pdsch_groups_prb_mcs_tbs'];gg=g['pdsch_groups_prb_mcs_tbs']
matched=[dict(prb=int(k.split(':')[0]),mcs=int(k.split(':')[1]),tbs_bits=int(k.split(':')[2]),cpu=cg[k],gpu=gg[k]) for k in cg.keys()&gg.keys() if min(cg[k]['n'],gg[k]['n'])>=100]
matched.sort(key=lambda r:min(r['cpu']['n'],r['gpu']['n']),reverse=True)
result=dict(conditions=dict(hardware='Spark NVIDIA GB10',gnb='CUDA acceleration all, frozen patched gNB binary',channel='Original profile-20261028 channel binary, experimental relay/fusion changes disabled',ue='Existing Claude b1d962ef build, CPU execution (GPU disabled) versus FFT/PDSCH/LDPC GPU mode, blocking synchronization',bandwidth_mhz=20,sample_rate_hz=23040000,cells=1,antennas='1x1',warmup_radio_seconds=10,measurement_radio_seconds=30,ue_cpus='13,14,17-19',zmq='Unchanged',mps='gNB, channel and GPU UEs share MPS'),primary_performance=rows,diagnostic_16ue=dict(gpu_pdsch_share=g['gpu_pdsch_share'],gpu_fft_fallback=g['gpu_fft_fallback'],cpu_dl_work_us=c['aggregate']['worker/DL/2'],gpu_dl_work_us=g['aggregate']['worker/DL/2'],cpu_dl_over_1ms_share=c['dl_over_1ms']/c['aggregate']['worker/DL/2']['n'],gpu_dl_over_1ms_share=g['dl_over_1ms']/g['aggregate']['worker/DL/2']['n'],gpu_pdsch_total_us=g['aggregate']['uedl/GPDSCH/2'],gpu_pdsch_completion_wait_us=g['aggregate']['uedl/GPT/4'],gpu_pdsch_event_span_us=g['aggregate']['uedl/GPG/2'],matched_allocation_groups=matched),limitations=['One clean performance run per mode and UE count; no confidence interval.', 'Frozen offered traffic and channel do not force identical actual PHY workload: HARQ/OLLA changes MCS and delivered payload.', '16-UE primary runs include RRC release during measurement; 8-UE primary runs have 30/30 valid segments and no scheduling-request-failure log messages.', 'Trace-enabled 16-UE runs diagnose stages and are separate from clean speed measurements; matched allocations pool UEs on heterogeneous CPU cores.', 'GPU event span includes stream scheduling intervals and host submission gaps, not only kernel arithmetic. Completion wait does not separately identify GPU queuing, execution and CPU wakeup.', 'Raw trace tails include incomplete buffered records; see trace-audit.json. Rare fallback-stage logs can end earlier; GPU offload share is approximate.', 'All primary runs have nonzero broker starvation counters, so no run qualifies as strict real time.'])
(root/'comparison.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps(rows,indent=2))
